// ═══ WHAT newFixedThreadPool ACTUALLY CREATES ═══
public static ExecutorService newFixedThreadPool(int nThreads) {
    return new ThreadPoolExecutor(
        nThreads, nThreads,            // core = max = fixed!
        0L, TimeUnit.MILLISECONDS,
        new LinkedBlockingQueue<>()    // UNBOUNDED! Integer.MAX_VALUE capacity!
    );
}
// Queue NEVER full → rejection handler NEVER fires!
// Tasks pile up forever → OOM!

// ═══ OTHER DANGEROUS FACTORY METHODS ═══
// newCachedThreadPool():
new ThreadPoolExecutor(0, Integer.MAX_VALUE, 60L, SECONDS, new SynchronousQueue<>());
// Creates a NEW thread for every task if none idle!
// 100K tasks → 100K threads → 100GB stack memory → OOM!

// newSingleThreadExecutor():
new ThreadPoolExecutor(1, 1, 0, MILLISECONDS, new LinkedBlockingQueue<>());
// Same unbounded queue problem! 1 worker, infinite queue!

// newScheduledThreadPool():
new ScheduledThreadPoolExecutor(corePoolSize);
// Uses DelayedWorkQueue — also unbounded!

// ═══ FIX: ThreadPoolExecutor with BOUNDED queue ═══
ThreadPoolExecutor SAFE = new ThreadPoolExecutor(
    10,                                    // core
    20,                                    // max (burst)
    60, TimeUnit.SECONDS,                 // idle timeout
    new LinkedBlockingQueue<>(500),       // BOUNDED! 500 max queued!
    r -> new Thread(r, "svc-worker-" + c.incrementAndGet()),  // named!
    new ThreadPoolExecutor.CallerRunsPolicy()  // back-pressure!
);
// Queue full + max workers busy → CallerRunsPolicy → caller slows down!
// BOUNDED memory! Predictable behavior! No OOM!

// ═══ SONARQUBE / ALIBABA RULE ═══
// SonarQube: squid:S2093 — "ThreadPool should be created by ThreadPoolExecutor"
// Alibaba Java Guide: "Do not use Executors to create thread pools"
// Reason: unbounded queue/threads = OOM risk in production!
