package com.bank.executors;

import org.junit.jupiter.api.Test;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import static org.assertj.core.api.Assertions.*;

class ExecutorsDangerousTest {

    // ═══ newFixedThreadPool: unbounded queue grows indefinitely ═══
    @Test
    void fixedPool_unboundedQueue_grows() {
        ExecutorService pool = Executors.newFixedThreadPool(1);
        ThreadPoolExecutor tpe = (ThreadPoolExecutor) pool;

        for (int i = 0; i < 10_000; i++) {
            pool.submit(() -> { try { Thread.sleep(1000); } catch (InterruptedException e) {} });
        }

        System.out.println("Queue size: " + tpe.getQueue().size());
        assertThat(tpe.getQueue().size()).isGreaterThan(9000);
        // 9999 tasks queued! In production: millions → OOM!
        pool.shutdownNow();
    }

    // ═══ SAFE: bounded queue with rejection ═══
    @Test
    void boundedPool_rejectsWhenFull() {
        AtomicInteger rejected = new AtomicInteger(0);
        ThreadPoolExecutor pool = new ThreadPoolExecutor(
            1, 2, 60, TimeUnit.SECONDS,
            new LinkedBlockingQueue<>(10),
            Executors.defaultThreadFactory(),
            (r, e) -> rejected.incrementAndGet()
        );

        for (int i = 0; i < 100; i++) {
            pool.submit(() -> { try { Thread.sleep(500); } catch (InterruptedException e) {} });
        }

        System.out.println("Rejected: " + rejected.get());
        assertThat(rejected.get()).isGreaterThan(0);  // excess rejected! Not queued!
        // Memory: bounded! No OOM!
        pool.shutdownNow();
    }

    // ═══ newCachedThreadPool: unbounded threads! ═══
    @Test
    void cachedPool_createsUnlimitedThreads() {
        ExecutorService pool = Executors.newCachedThreadPool();
        ThreadPoolExecutor tpe = (ThreadPoolExecutor) pool;

        for (int i = 0; i < 1000; i++) {
            pool.submit(() -> { try { Thread.sleep(500); } catch (InterruptedException e) {} });
        }

        try { Thread.sleep(100); } catch (InterruptedException e) {}
        System.out.println("Pool size: " + tpe.getPoolSize());
        assertThat(tpe.getPoolSize()).isGreaterThan(500);
        // 1000 threads created! In production: 100K → OOM (stack memory)!
        pool.shutdownNow();
    }

    // ═══ CORRECT production pool ═══
    @Test
    void productionPool_bounded_named_rejection() throws InterruptedException {
        AtomicInteger counter = new AtomicInteger(0);
        AtomicInteger rejected = new AtomicInteger(0);

        ThreadPoolExecutor pool = new ThreadPoolExecutor(
            5, 10, 60, TimeUnit.SECONDS,
            new LinkedBlockingQueue<>(100),
            r -> new Thread(r, "stmt-worker-" + counter.incrementAndGet()),
            (r, e) -> { rejected.incrementAndGet(); r.run(); }  // log + CallerRuns!
        );

        for (int i = 0; i < 200; i++) {
            pool.submit(() -> { try { Thread.sleep(50); } catch (InterruptedException e) {} });
        }

        pool.shutdown();
        pool.awaitTermination(30, TimeUnit.SECONDS);
        System.out.println("Rejected (caller-ran): " + rejected.get());
    }
}
